// Calcula dias em aberto e sinaliza atraso de SLA
const SLA_DIAS = 30; // ajuste conforme sua política interna
const hoje = new Date();

const resultados = [];

for (const item of $input.all()) {
  const dados = item.json;
  const status = (dados.status || '').trim();

  // só interessa quem ainda está em aberto
  if (status !== 'Em Investigação' && status !== 'Recebido') {
    continue;
  }

  const dataOcorrencia = new Date(dados.data_ocorrencia);
  if (isNaN(dataOcorrencia.getTime())) {
    continue; // ignora linhas com data inválida/vazia
  }

  const diasEmAberto = Math.floor((hoje - dataOcorrencia) / (1000 * 60 * 60 * 24));
  const atrasado = diasEmAberto > SLA_DIAS;

  resultados.push({
    json: {
      caso_id: dados.caso_id,
      categoria: dados.categoria,
      status: status,
      data_ocorrencia: dados.data_ocorrencia,
      dias_em_aberto: diasEmAberto,
      sla_dias: SLA_DIAS,
      atrasado: atrasado
    }
  });
}

return resultados;

